const assert = require('node:assert/strict');
const path = require('node:path');
const vm = require('node:vm');
const { createRequire } = require('node:module');
const pluginRequire = createRequire(path.resolve(__dirname, '../plugin/package.json'));
const { buildSync } = pluginRequire('esbuild');
const code = buildSync({
  absWorkingDir: path.resolve(__dirname, '../plugin'),
  entryPoints: ['src/main.ts'], bundle: true, write: false, platform: 'node', format: 'cjs',
  external: ['obsidian', 'electron'], loader: { '.svg': 'text', '.wasm': 'binary' },
}).outputFiles[0].text;
const stub = { Plugin: class {}, PluginSettingTab: class {}, ItemView: class {}, Modal: class {}, Notice: class {} };
const context = {
  module: { exports: {} }, Buffer, structuredClone,
  require: name => name === 'obsidian' ? stub : pluginRequire(name),
};
vm.runInNewContext(code, context);
const selection = title => ({
  paths: [title + '.md'], title, intent: '', preserveOrder: false, style: 'study',
  writingMode: 'original', studyAids: 'none', useAI: false, sendToKobo: true,
  step: 1, active: true,
});

test('both saves reach the available server when the last studio closes during an upload', async () => {
  const plugin = new context.module.exports.default();
  plugin.state = { composer: selection('A') };
  plugin.app = { workspace: { getLeavesOfType: () => [] } };
  let saved;
  plugin.saveData = async value => { saved = structuredClone(value); };
  const received = [];
  let acknowledge;
  let started;
  const firstStarted = new Promise(resolve => { started = resolve; });
  plugin.api = async (_route, body) => {
    if (body.title === 'A') {
      started();
      await new Promise(resolve => { acknowledge = resolve; });
    }
    received.push(body.title);
  };
  const first = plugin.parkComposer(false);
  await firstStarted;
  plugin.state.composer = selection('B');
  const lastClosed = plugin.leftStudio();
  await plugin.save();
  await new Promise(resolve => setImmediate(resolve));
  acknowledge();
  await Promise.all([first, lastClosed]);
  assert.deepEqual(received.sort(), ['A', 'B'], `pending after both saves: ${JSON.stringify(saved)}`);
});

